// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
return [{
  json: {
    paperless_url: pw('paperless_url'),
    // Die Adresse von paper-werk aus Sicht von n8n. Im Stack der
    // Docker-Servicename, nicht die Browser-Adresse.
    paperwerk_url: String(pw('paperwerk_url')).replace(/\/+$/, ''),

    // ── fachlich ──
    // Die Namen der Custom Fields, aus denen gelesen wird. Sie muessen zu
    // dem passen, was "manage.py paperless_einrichten" in paper-werk
    // anlegt; dort ist die verbindliche Liste.
    feld_netto: 'Nettobetrag',
    feld_nummer: 'Rechnungsnummer',
    feld_datum: 'Rechnungsdatum',
    feld_projekt: 'Projektnummer',
    // Der Tag, der diesen Lauf ausgeloest hat, und der, auf den er
    // umgesetzt wird. Was nach dem Lauf noch den ersten traegt, ist nicht
    // durchgekommen; das ist die ganze Fehlerliste.
    tag_offen: 'Paper-Werk senden',
    tag_fertig: 'Paper-Werk gesendet',
    // Trägt das Dokument diesen Tag, hat die Erkennung XML im PDF
    // gefunden: Dann geht die Datei selbst an paper-werk und nicht die
    // Felder, mit allen Positionen der Rechnung.
    tag_erechnung: 'E-Rechnung',
  }
}];

// Dokument-ID aus dem Paperless-Webhook holen.
// Body kann { doc_id }, { id } oder { doc_url } enthalten, nach derselben
// Verabredung wie in felder-erkennen-mistral.
const body = $('Webhook').first().json.body ?? {};
let id = body.doc_id ?? body.id;
if (!id && body.doc_url) {
  id = String(body.doc_url).match(/\/documents\/(\d+)/)?.[1];
}
if (!id) throw new Error('Keine doc_id/doc_url im Webhook-Body');
return [{ json: { id: Number(id) } }];

// Den Namen des Korrespondenten nachschlagen.
//
// Paperless liefert am Dokument nur seine Kennung. paper-werk will den
// NAMEN: Kennungen sind je Anlage andere, ein Name ist derselbe, und er
// ist das, was der Mensch im Archiv sieht.
const dok = $('Dokument holen').first().json;
const alle = $json.results ?? [];
const treffer = alle.find((k) => k.id === dok.correspondent);
return [{
  json: { ...dok, correspondent_name: treffer ? treffer.name : '' },
}];

// Aus dem Dokument und seinen Custom Fields wird die Nutzlast fuer
// paper-werk.
//
// **Namen statt Kennungen, und deshalb dieser Umweg.** Paperless liefert
// Custom Fields als { field: 15, value: "EUR1758.00" }; die 15 ist je
// Anlage eine andere. Gelesen wird deshalb ueber die Feldliste, die der
// Knoten davor geholt hat.
const cfg = $('Konfiguration').first().json;
// **"Korrespondent zuordnen" und nicht "Dokument holen".** Der rohe
// Dokumentknoten kennt nur die KENNUNG des Korrespondenten; den Namen
// haengt der Knoten danach an. Wer hier auf "Dokument holen" zugreift,
// bekommt ein Dokument ohne correspondent_name, und der Workflow bricht
// mit "hat keinen Korrespondenten" ab, obwohl einer gesetzt ist.
const dok = $('Korrespondent zuordnen').first().json;
const felder = $('Feldliste holen').first().json.results ?? [];

// Name -> Kennung, case-insensitive: Wer ein Feld von Hand anlegt,
// schreibt es irgendwann klein.
const nachName = {};
for (const f of felder) nachName[String(f.name).toLowerCase()] = f.id;

const kennung = (name) => {
  const id = nachName[String(name).toLowerCase()];
  if (id === undefined) {
    throw new Error('In Paperless gibt es kein Zusatzfeld "' + name + '". '
      + 'In paper-werk anlegen lassen: manage.py paperless_einrichten');
  }
  return id;
};

const werte = {};
for (const eintrag of (dok.custom_fields ?? [])) {
  werte[eintrag.field] = eintrag.value;
}

const lies = (name) => {
  const roh = werte[kennung(name)];
  return roh === null || roh === undefined ? '' : String(roh).trim();
};

// Ein monetary-Feld traegt den Waehrungscode im Wert: "EUR1758.00".
// Genauso, wie paper-werk ihn beim Hochladen seiner eigenen Belege
// voranstellt; hier wird er wieder abgeschnitten.
const betrag = (roh) => roh.replace(/^[A-Z]{3}/, '').trim();

const netto = betrag(lies(cfg.feld_netto));
const nummer = lies(cfg.feld_nummer);
const datum = lies(cfg.feld_datum);
const projekt = lies(cfg.feld_projekt);

// **Vor dem Senden pruefen und nicht danach.** paper-werk wuerde es auch
// bemaengeln, aber die Meldung dort spricht von Feldnamen der
// Schnittstelle; hier lassen sich die Namen nennen, die der Mensch in
// Paperless vor sich sieht.
const fehlend = [];
if (!netto) fehlend.push(cfg.feld_netto);
if (!nummer) fehlend.push(cfg.feld_nummer);
if (!datum) fehlend.push(cfg.feld_datum);
if (fehlend.length) {
  throw new Error('Am Dokument ' + dok.id + ' fehlen: ' + fehlend.join(', ')
    + '. In Paperless nachtragen und den Tag "' + cfg.tag_offen
    + '" erneut setzen.');
}

const lieferant = dok.correspondent_name || '';
if (!lieferant) {
  throw new Error('Dokument ' + dok.id + ' hat keinen Korrespondenten; '
    + 'ohne ihn weiss paper-werk nicht, von wem die Rechnung ist.');
}

return [{
  json: {
    id: dok.id,
    tags: dok.tags ?? [],
    nutzlast: {
      paperless_id: dok.id,
      lieferant,
      nummer,
      datum,
      betrag_netto: netto,
      projekt,
      notiz: 'Aus Paperless übernommen.',
    },
  },
}];

// Den Tag umsetzen: "Paper-Werk senden" raus, "Paper-Werk gesendet" rein.
//
// **Erst jetzt, nach der Antwort von paper-werk.** Bricht der Uebertrag
// ab, bleibt der alte Tag stehen, und damit ist das Dokument in Paperless
// weiterhin als offen sichtbar. Der Tag IST die Arbeitsliste.
const cfg = $('Konfiguration').first().json;
// Beim Namen und nicht über $json: Hier laufen beide Wege zusammen,
// Felder und E-Rechnung.
const dok = $('Dokument holen').first().json;
const alle = $('Tagliste holen').first().json.results ?? [];

const finde = (name) => {
  const t = alle.find((x) => String(x.name).toLowerCase() === String(name).toLowerCase());
  if (!t) {
    throw new Error('In Paperless gibt es kein Schlagwort "' + name + '". '
      + 'In paper-werk anlegen lassen: manage.py paperless_einrichten');
  }
  return t.id;
};

const offen = finde(cfg.tag_offen);
const fertig = finde(cfg.tag_fertig);

const neu = (dok.tags ?? []).filter((t) => t !== offen);
if (!neu.includes(fertig)) neu.push(fertig);

return [{ json: { id: dok.id, tags: neu } }];

// Felder oder E-Rechnung? Das hat die Erkennung schon entschieden und am
// Tag festgehalten; hier wird es nur nachgelesen.
const cfg = $('Konfiguration').first().json;
const dok = $('Dokument holen').first().json;
const tags = $('Tagliste holen').first().json.results ?? [];
const felder = $json.results ?? [];

const tag = tags.find((t) => String(t.name).toLowerCase() === cfg.tag_erechnung.toLowerCase());
const erechnung = !!tag && (dok.tags ?? []).includes(tag.id);

// Die Projektnummer, die ein Mensch in Paperless geprüft hat. Für die
// E-Rechnung ist sie das einzige Feld, das mitgeht; alles andere steht
// im XML. Leer heißt: paper-werk nimmt die Projektreferenz der Rechnung.
const feld = felder.find((f) => String(f.name).toLowerCase() === cfg.feld_projekt.toLowerCase());
const eintrag = feld ? (dok.custom_fields ?? []).find((c) => c.field === feld.id) : null;
const projekt = eintrag && eintrag.value ? String(eintrag.value).trim() : '';

return [{ json: { id: dok.id, erechnung, projekt } }];
